export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
export const defaultDesign=()=>({type:'polo',fabric:'cotton',color:'cobalt',quantity:30,price:68});
export function freshGame(label='Your label',seed=Date.now()){return {version:1,label:label.trim().slice(0,32)||'Your label',week:1,cash:8000,followers:250,reputation:20,revenue:0,unitsSold:0,inventory:[],history:[],ordersThisWeek:0,productionThisWeek:0,seed:seed>>>0,finished:false};}
export function unitCost(d){return TYPES.find(t=>t.id===d.type).base+FABRICS.find(f=>f.id===d.fabric).extra;}
export function validateDesign(d){return d&&TYPES.some(t=>t.id===d.type)&&FABRICS.some(f=>f.id===d.fabric)&&COLORS.some(c=>c.id===d.color)&&Number.isInteger(d.quantity)&&d.quantity>=10&&d.quantity<=150&&Number.isInteger(d.price)&&d.price>=25&&d.price<=250;}
export function placeOrder(s,d){if(s.finished)throw Error('This season has ended.');if(!validateDesign(d))throw Error('Choose a quantity from 10–150 and a price from $25–$250.');if(s.ordersThisWeek>=3)throw Error('Your studio can produce three designs each week.');const cost=unitCost(d)*d.quantity;if(cost>s.cash-250)throw Error('Keep at least $250 for this week’s studio costs.');const n=structuredClone(s);n.cash-=cost;n.productionThisWeek+=cost;n.ordersThisWeek++;n.inventory.push({...d,id:`${s.week}-${s.ordersThisWeek}-${s.inventory.length}`,cost:unitCost(d),remaining:d.quantity,sold:0,created:s.week});return n;}
function random(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
export function forecast(s,d,campaign='organic',choice=0){const t=TYPES.find(t=>t.id===d.type),f=FABRICS.find(f=>f.id===d.fabric),e=EVENTS[Math.min(s.week-1,11)],c=CAMPAIGNS.find(c=>c.id===campaign),ev=e.choices[choice]||e.choices[0];const fair=t.value*f.quality*(.85+s.reputation/140);const priceFactor=Math.min(1.8,Math.max(.06,(fair/d.price)**2.3));const trend=(e.type===d.type?1.35:1)*(e.color===d.color?1.12:1);return (14+s.followers*.012+s.reputation*.12)*priceFactor*trend*c.boost*ev.demand*(e.market||1);}
export function launch(s,campaign='organic',choice=0){if(s.finished)throw Error('This season has ended.');const c=CAMPAIGNS.find(c=>c.id===campaign),e=EVENTS[s.week-1],ev=e?.choices[choice];if(!c||!ev)throw Error('Choose a valid campaign and event response.');const expenses=250+c.cost+ev.cost;if(s.cash<expenses)throw Error(`You need ${money(expenses)} for this campaign, event, and studio costs. Choose a cheaper plan.`);const n=structuredClone(s);n.cash-=expenses;n.reputation=Math.min(100,n.reputation+(ev.rep||0));n.followers+=ev.followers||0;const before=n.revenue;let sold=0,cogs=0;const active=n.inventory.filter(i=>i.remaining>0);const saturation=1/Math.max(1,active.length);const lines=[];for(const item of active){const demand=forecast(n,item,campaign,choice)*saturation*(.82+random(n)*.36);const count=Math.min(item.remaining,Math.floor(demand));item.remaining-=count;item.sold+=count;sold+=count;cogs+=count*item.cost;const revenue=count*item.price;n.cash+=revenue;n.revenue+=revenue;lines.push({type:item.type,color:item.color,sold:count,revenue,remaining:item.remaining});}n.unitsSold+=sold;n.followers+=Math.round(c.followers+sold*.85);n.reputation=Math.min(100,Math.max(0,n.reputation+(sold>0?2:-2)));const revenue=n.revenue-before;const report={week:s.week,event:e.title,campaign:c.name,revenue,sold,expenses,production:s.productionThisWeek,profit:revenue-cogs-expenses,cash:n.cash,followers:n.followers,lines};n.history.push(report);n.ordersThisWeek=0;n.productionThisWeek=0;n.week++;n.finished=n.week>12||n.cash<250;return {state:n,report};}
export function outcome(s){if(s.week<=12&&s.cash<250)return {title:'A lesson in timing',rank:'Season closed',text:'Your studio ran out of operating cash. Start again with smaller orders and a little more room in the budget.'};if(s.cash>=20000&&s.reputation>=65)return {title:'The next big name',rank:'Breakout label',text:'A profitable season, a clear point of view, and a reputation that travels. Your label has arrived.'};if(s.cash>=12000)return {title:'A label with a future',rank:'Independent success',text:'You built a profitable foundation. Your next collection starts with a stronger studio and a real audience.'};if(s.cash>=8000)return {title:'Finding your signature',rank:'Emerging designer',text:'You finished with your starting cash intact. Now you know which ideas deserve a second season.'};return {title:'Every label starts somewhere',rank:'First-season founder',text:'You made it through the season. Refine your prices, buy less stock, and let demand guide your next move.'};}
export function validSave(s){return s?.version===1&&typeof s.label==='string'&&s.label.length<=32&&Number.isInteger(s.week)&&s.week>=1&&s.week<=13&&['cash','followers','reputation','revenue','unitsSold','seed','ordersThisWeek','productionThisWeek'].every(k=>Number.isFinite(s[k])&&s[k]>=0)&&typeof s.finished==='boolean'&&Array.isArray(s.inventory)&&s.inventory.length<=36&&s.inventory.every(i=>validateDesign(i)&&Number.isInteger(i.remaining)&&i.remaining>=0&&i.remaining<=i.quantity&&Number.isFinite(i.cost)&&Number.isFinite(i.sold))&&Array.isArray(s.history)&&s.history.length<=12;}
